  }
  const tw=src.reduce((s,v)=>s+v[4],0);
  const act=(aS+aS2*0.4)/tw, inh=(iS+iS2*0.4)/tw;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+Math.cos(sy*0.06+t)*3+t*0.7)*0.15+Math.sin(Math.sin(sx*0.05+t)*4+sy*0.07-t*0.9)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
