  const reaction2=Math.tanh((act*1.3-inh*0.5+bg*0.15-spiral*0.3)*1.8);
  const combined=reaction*0.7+reaction2*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.tanh((Math.sin(sx*0.22+t*0.3)*Math.cos(sy*0.18-t*0.2)+Math.sin((sx-sy)*0.13-t*0.7)*0.4)*1.2)*0.2;
  const dx=Math.cos(sx*0.15)*Math.sin(sy*0.15)*0.15, dy=Math.sin(sx*0.15)*Math.cos(sy*0.15)*0.15;
  const edge=Math.sqrt(dx*dx+dy*dy);
  const blend=combined*0.65+(cell+cell2)*0.2+edge*0.15, v=blend*0.5+0.5;
